    "terraformSnippet": "resource \"google_assured_workloads_workload\" \"fedramp_workload\" {\n  compliance_regime = \"FEDRAMP_HIGH\"\n  display_name      = \"defense-fedramp-high-prod\"\n  location          = \"us-central1\"\n  organization      = \"123456789\"\n  resource_settings {\n    resource_type = \"CONSUMER_FOLDER\"\n  }\n}",
    "officialDocUrl": "https://cloud.google.com/assured-workloads/docs/overview",
